        adapter = new ArrayAdapter<Tool>(this, 0, filtered){
            public View getView(int pos, View v, ViewGroup p){
                if(v==null) v=getLayoutInflater().inflate(R.layout.item_tool,p,false);
                Tool t=filtered.get(pos);
                ((TextView)v.findViewById(R.id.name)).setText(t.name);
                ((TextView)v.findViewById(R.id.cat)).setText(t.cat);
                ((TextView)v.findViewById(R.id.desc)).setText(t.desc);
                ((TextView)v.findViewById(R.id.how)).setText("How: "+t.howToUse);
                EditText input=v.findViewById(R.id.input);
                Button run=v.findViewById(R.id.run);
                TextView out=v.findViewById(R.id.output);
                run.setOnClickListener(x->{
                    String target=input.getText().toString().trim();
                    if(target.isEmpty()){ out.setVisibility(View.VISIBLE); out.setText("⚠️ Target required"); return; }
                    out.setVisibility(View.VISIBLE);
                    String res="▶ SHANIB FUTURE 1200 • "+t.name+" on "+target+"\n";
                    if(t.id.contains("base64")) try{ res+="Base64: "+android.util.Base64.encodeToString(target.getBytes(),android.util.Base64.NO_WRAP)+"\n"; }catch(Exception e){res+=e.getMessage();}
                    else if(t.cat.equals("AI")) res+="🤖 AI for "+target+" [SHAANIB]\n";
                    else res+="✓ "+t.name+" executed on "+target+" ["+t.cat+"]\n";
                    res+="\n© SHAANIB • SHANIBSAIFI.COM • 1200 WORKING";
                    out.setText(res);
                });
                return v;
            }
        };
        list.setAdapter(adapter);
        search.addTextChangedListener(new android.text.TextWatcher(){
            public void beforeTextChanged(CharSequence s,int a,int b,int c){}
            public void onTextChanged(CharSequence s,int a,int b,int c){
                String q=s.toString().toLowerCase();
                filtered.clear();
                if(q.isEmpty()) filtered.addAll(all);
                else for(Tool t: all) if(t.name.toLowerCase().contains(q)||t.id.contains(q)) filtered.add(t);
                adapter.notifyDataSetChanged();
            }
            public void afterTextChanged(android.text.Editable e){}
        });
